'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((v||0)/100);
let csrf='', dashboard={users:[],payments:[],analytics:{}};
async function api(path,data){const response=await fetch(path,{credentials:'same-origin',method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed.');return result;}
function notice(text){$('#admin-message').textContent=text;$('#admin-message').classList.remove('hidden');}
function view(name){$$('[data-panel]').forEach(p=>p.classList.toggle('hidden',p.dataset.panel!==name));$$('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===name));history.replaceState({},'',`#${name}`);$('#view-title').textContent=$(`[data-view="${name}"]`).textContent.replace(/^[^a-zA-Z]+/,'').trim();}
function stat(label,value){return `<article class="admin-stat"><span>${escapeHTML(label)}</span><strong>${escapeHTML(value)}</strong></article>`;}
async function refresh(){const session=await api('/api/session');csrf=session.csrf;if(session.user?.role!=='admin'){location.replace('/Oracle691?admin=signin');return;}dashboard=await api('/api/admin/dashboard');render();await loadSettings();}
function render(){const s=dashboard.summary;$('#admin-stats').innerHTML=stat('Registered users',s.users)+stat('Active accounts',s.active)+stat('Captured payments',s.payments)+stat('Captured volume · USD',money(s.revenue));$('#revenue-plans').innerHTML=Object.entries(dashboard.revenue_by_plan).map(([plan,value])=>`<div class="row-item"><strong>${money(value)}</strong><p>${escapeHTML(plan==='investment'?'Investment-linked':plan==='daily_contract'?'Plan 3 bot contracts':'Prepaid Plus')}</p></div>`).join('')||'<p class="muted-empty">No captured payments yet.</p>';$('#audit-list').innerHTML=dashboard.audit.map(row=>`<div class="row-item"><p>${escapeHTML(row.action)}</p><small>${new Date(row.time*1000).toLocaleString()} · ${escapeHTML(row.target)}</small></div>`).join('')||'<p class="muted-empty">No administration events yet.</p>';renderUsers();const form=$('#admin-profile');form.elements.name.value=dashboard.profile.name;form.elements.email.value=dashboard.profile.email;form.elements.current_password.value='';form.elements.new_password.value='';$('#payment-report').innerHTML=dashboard.payments.map(p=>`<tr><td>${escapeHTML(p.payment_id)}</td><td>${escapeHTML(p.plan_name||p.plan)}</td><td>${money(p.amount)}</td><td>${escapeHTML(p.status)}</td></tr>`).join('')||'<tr><td colspan="4">No captured payments yet.</td></tr>';renderAnalytics();renderContracts();}
function renderUsers(){const search=$('#user-search').value.toLowerCase();$('#users-body').innerHTML=dashboard.users.filter(u=>(u.name+' '+u.email).toLowerCase().includes(search)).map(u=>`<tr><td>${escapeHTML(u.name)}<small>${escapeHTML(u.email)}</small></td><td>${escapeHTML(u.provider)}</td><td>${escapeHTML(u.role)}</td><td><span class="pill status">${u.disabled?'Suspended':'Active'}</span></td><td><button class="secondary" data-edit="${escapeHTML(u.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="5">No matching users.</td></tr>';$$('[data-edit]').forEach(button=>button.onclick=()=>editUser(button.dataset.edit));}
function editUser(id){const user=dashboard.users.find(u=>u.id===id);const form=$('#edit-user-form');for(const key of ['id','name','email','role'])form.elements[key].value=user[key];form.elements.email.readOnly=user.provider!=='password';form.elements.status.value=user.disabled?'disabled':'active';$('#edit-user-error').textContent='';$('#edit-user-dialog').showModal();}
function renderAnalytics(){const days=Object.entries(dashboard.analytics).sort(([a],[b])=>a.localeCompare(b));const sums=days.reduce((a,[day,d])=>({views:a.views+Object.values(d.views).reduce((x,y)=>x+y,0),visitors:a.visitors+d.visitors.length,checkouts:a.checkouts+(d.events['checkout.started']||0)}),{views:0,visitors:0,checkouts:0});$('#analytics-totals').innerHTML=stat('Page views',sums.views)+stat('Daily session totals',sums.visitors)+stat('Checkout starts',sums.checkouts)+stat('Tracked days',days.length);const recent=days.slice(-14),max=Math.max(1,...recent.map(([,d])=>Object.values(d.views).reduce((x,y)=>x+y,0)));$('#analytics-chart').innerHTML=recent.map(([day,d])=>{const views=Object.values(d.views).reduce((x,y)=>x+y,0);return `<div class="chart-day" style="height:${Math.max(3,views/max*100)}%" title="${day}: ${views} views"><span>${day.slice(5)}</span></div>`;}).join('')||'<p class="muted-empty">Page views will appear after visitors use the portal.</p>';$('#analytics-body').innerHTML=days.reverse().map(([day,d])=>`<tr><td>${day}</td><td>${Object.values(d.views).reduce((x,y)=>x+y,0)}</td><td>${d.visitors.length}</td><td>${(d.events['plan.investment']||0)+(d.events['plan.prepaid_plus']||0)}</td><td>${d.events['checkout.started']||0}</td></tr>`).join('')||'<tr><td colspan="5">No traffic recorded yet.</td></tr>';}
async function loadSettings(){const result=await api('/api/admin/settings');const groups={Razorpay:['RAZORPAY_HOSTED_LIVE','RAZORPAY_PAGE_INVESTMENT','RAZORPAY_PAGE_PREPAID_PLUS','RAZORPAY_KEY_ID','RAZORPAY_KEY_SECRET','RAZORPAY_WEBHOOK_SECRET','ORACLE_CHECKOUT_ENABLED'],Google:['GOOGLE_CLIENT_ID','GOOGLE_CLIENT_SECRET','GOOGLE_REDIRECT_URI'],Facebook:['FACEBOOK_CLIENT_ID','FACEBOOK_CLIENT_SECRET','FACEBOOK_GRAPH_VERSION','FACEBOOK_REDIRECT_URI'],LinkedIn:['LINKEDIN_CLIENT_ID','LINKEDIN_CLIENT_SECRET','LINKEDIN_REDIRECT_URI']};$('#settings-groups').innerHTML=Object.entries(groups).map(([group,keys])=>`<section class="panel"><div class="panel-heading"><h2>${group}</h2><span class="pill">${(group==='Razorpay'?(result.checkout_enabled || result.fields.RAZORPAY_PAGE_INVESTMENT.configured || result.fields.RAZORPAY_PAGE_PREPAID_PLUS.configured):result.services[group.toLowerCase()])?'Active · credentials saved':'Awaiting setup'}</span></div><div class="setting-grid">${keys.map(key=>{const f=result.fields[key];const input=key==='ORACLE_CHECKOUT_ENABLED'?`<select name="${key}"><option value="false" ${f.value!=='true'?'selected':''}>Disabled</option><option value="true" ${f.value==='true'?'selected':''}>Enabled</option></select>`:`<input name="${key}" type="${f.secret?'password':'text'}" autocomplete="off" value="${escapeHTML(f.value)}" placeholder="${f.secret&&f.configured?'Saved · leave blank to keep':key.endsWith('_REDIRECT_URI')?'http://127.0.0.1:8000/auth/'+group.toLowerCase()+'/callback':''}">`;return `<div class="setting-field"><label>${escapeHTML(f.label)}${input}</label><small class="${f.configured?'secret-status':''}">${f.configured?'Configured':'Not configured'}</small><label class="clear-setting"><input type="checkbox" data-clear="${key}"> Clear saved value</label></div>`;}).join('')}</div></section>`).join('');const toggle=$('#provider-settings [name=ORACLE_CHECKOUT_ENABLED]');if(toggle)toggle.onchange=()=>{toggle.dataset.changed='true';};}
$('#provider-settings').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const values=Object.fromEntries(new FormData(event.target)),clear=$$('[data-clear]:checked').map(e=>e.dataset.clear);for(const key of clear)delete values[key];const toggle=event.target.elements.ORACLE_CHECKOUT_ENABLED;if(toggle && toggle.dataset.changed!=='true')delete values.ORACLE_CHECKOUT_ENABLED;const result=await api('/api/admin/settings',{values,clear});notice(result.message);await loadSettings();}catch(error){notice(error.message);}finally{button.disabled=false;}};
$('#admin-profile').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await api('/api/admin/profile',Object.fromEntries(new FormData(event.target)));notice('Profile saved.');await refresh();}catch(error){notice(error.message);}finally{button.disabled=false;}};
$('#edit-user-form').onsubmit=async event=>{event.preventDefault();const value=Object.fromEntries(new FormData(event.target));value.disabled=value.status==='disabled';delete value.status;try{await api('/api/admin/users',value);$('#edit-user-dialog').close();notice('User profile and access updated.');await refresh();}catch(error){$('#edit-user-error').textContent=error.message;}};
$$('[data-view]').forEach(button=>button.onclick=()=>view(button.dataset.view));$('#user-search').oninput=renderUsers;$('#admin-refresh').onclick=()=>refresh().catch(error=>notice(error.message));$('#edit-user-dialog .close').onclick=()=>$('#edit-user-dialog').close();$('#admin-logout').onclick=async()=>{try{await api('/api/logout',{});location.assign('/Oracle691');}catch(error){notice(error.message);}};refresh().then(()=>{const name=location.hash.slice(1);if(['overview','contracts','users','profile','reports','analytics','settings','setup'].includes(name))view(name);}).catch(error=>notice(error.message));
function renderContracts(){const contracts=Array.isArray(dashboard.daily_contracts?.contracts)?dashboard.daily_contracts.contracts:[],selector=$('#contract-selector');selector.innerHTML=contracts.map(c=>`<option value="${escapeHTML(c.contractId)}">${escapeHTML(c.accessDays)} day · ${escapeHTML(c.predictionCount)} predictions · ${escapeHTML(c.status)}</option>`).join('')||'<option value="">No published contracts</option>';const show=()=>{const c=contracts.find(item=>item.contractId===selector.value)||contracts[0];if(!c){$('#contract-readiness').textContent='Awaiting an authenticated production contract round.';$('#contract-stats').innerHTML='';return;}const price=Number(c.contractPriceCents||c.accessFeeCents||0),capital=Number(c.requiredExchangeCapitalCents||Math.ceil(Number(c.requiredBatchCapitalUsd||0)*100)),known=Number(c.knownActualizationCashCents||price+capital),reasons=(c.blockedReasons||[]).join('; ');$('#contract-readiness').textContent=`${c.status==='available'?'Published':'Held'} · bot ${c.botDeploymentStatus||'not-defined'} · execution ${c.executionEligible?'enabled':'disabled'}${reasons?' · '+reasons:''}`;$('#contract-stats').innerHTML=stat('Batch predictions',c.predictionCount||0)+stat('Contract cap',c.predictionCap||0)+stat('Reserve',`${Number(c.capitalReservePercent||0)}%`)+stat('Per-trade budget',money(Math.ceil(Number(c.perTradeCapitalUsd||0)*100)));$('#contract-purchase').textContent=money(price);$('#contract-capital').textContent=money(capital);$('#contract-known-total').textContent=money(known);};selector.onchange=show;show();}
